            (Simd32x4::from(other[e3215]) * Simd32x4::from([wedge_g1[0], wedge_g1[1], wedge_g1[2], wedge_g2[3]]))
                + (Simd32x4::from([wedge_g2[1], wedge_g2[2], wedge_g2[0], wedge_g3[0]]) * other.group0().zxyx())
                + Simd32x3::from(0.0).with_w((wedge_g3[1] * other[e4315]) + (wedge_g3[2] * other[e4125]))
