                        - (wedge_g2_xyz[2] * other[e43])
                        - (wedge_g0[1] * other[e25])
                        - (wedge_g0[2] * other[e35])
                        - (wedge_g1[0] * other[e23])
                        - (wedge_g1[1] * other[e31])
                        - (wedge_g1[2] * other[e12])
