impl ProjectOrthogonallyOnto<Plane> for RoundPoint {
    type Output = RoundPoint;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        4       10        0        0
    //    simd2        0        1        0      N/A
    //    simd3        3        6        0      N/A
    //    simd4        3        1        0      N/A
    // Totals...
    // yes simd       10       18        0      N/A
    //  no simd       25       34        0        0
    fn project_orthogonally_onto(self, other: Plane) -> Self::Output {
        use crate::elements::*;
        let wedge_g0 = Simd32x3::from(self[e4] * -1.0) * other.group0().xyz();
        let wedge_g1_xyz =
            (other.group0().yzx() * self.group0().zxy()) + Simd32x2::from(0.0).with_z((other[e4315] * self[e1]) * -1.0) - (other.group0().zx() * self.group0().yz()).with_z(0.0);
        let wedge_g2 = (Simd32x3::from(other[e3215]) * self.group0().xyz()) + (Simd32x3::from(self[e5]) * other.group0().xyz());
        RoundPoint::from_groups(
            // e1, e2, e3, e4
            (other.group0().yzxx() * wedge_g1_xyz.zxy().with_w(wedge_g0[0])) + Simd32x3::from(0.0).with_w((wedge_g0[1] * other[e4315]) + (wedge_g0[2] * other[e4125]))
                - (wedge_g0 * Simd32x3::from(other[e3215])).with_w(0.0)
                - (wedge_g1_xyz.yzx() * other.group0().zxy()).with_w(0.0),
            // e5
            -(wedge_g2[0] * other[e4235]) - (wedge_g2[1] * other[e4315]) - (wedge_g2[2] * other[e4125]) - (other[e3215] * other[e3215] * self[e4]),
        )
    }
}
